// Returns each item's `n`, uppercased when `a` is 1. Skips null/undefined items.
function proc(items) {
  return items
    .filter((item) => item != null)
    // Loose equality kept on purpose: `a` may be "1" or true as well as 1.
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// Splits a comma-separated string into trimmed, non-empty parts.
function f2(str) {
  return str
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

