const test = require('node:test');
const assert = require('node:assert');
const { proc, f2 } = require('./util');

test('proc', () => {
  const items = [{ a: 1, n: 'x' }, null, { a: 0, n: 'y' }, undefined, { a: '1', n: 'z' }];
  assert.deepStrictEqual(proc(items), ['X', 'y', 'Z']);
});

test('f2', () => {
  assert.deepStrictEqual(f2(' a, b ,, c ,'), ['a', 'b', 'c']);
});

